<script>
 export let hosts,api,onjob,onlogs,onterminal;
 let hostId=hosts[0]?.id||'',rows=[],checkpoints=[],pending=false,error='',showCompose=false,confirm=null,typed='',creation=false;
 let form={name:'',image:'',environment:[],ports:[],mounts:[],restart:'unless-stopped',start:false,command:[]},environment='',ports='',mounts='',command='';
 function dialog(node){node.showModal();return{destroy(){node.close();}};}
 async function load(){if(!hostId)return;pending=true;error='';try{const result=await api(`/hosts/${hostId}/containers`);rows=result.containers;checkpoints=(await api(`/hosts/${hostId}/container-checkpoints`)).checkpoints;}catch(e){error=e.message;}finally{pending=false;}}
 import {onMount} from 'svelte';onMount(load);
 function ask(row,action,point=null){typed='';confirm={row,action,point};}
 async function act(event){event.preventDefault();pending=true;error='';try{const result=await api(`/hosts/${hostId}/containers/${confirm.row.ID}/actions`,{method:'POST',body:JSON.stringify({action:confirm.action,confirm:typed,checkpoint:confirm.point?.id||''})});await onjob(result.job.id);confirm=null;}catch(e){error=e.message;}finally{pending=false;}}
 function lines(text){return text.split('\n').map(v=>v.trim()).filter(Boolean);}
 async function create(event){event.preventDefault();pending=true;error='';try{const result=await api(`/hosts/${hostId}/containers`,{method:'POST',body:JSON.stringify({...form,command:lines(command),environment:lines(environment),ports:lines(ports),mounts:lines(mounts),confirm:typed})});creation=false;await onjob(result.job.id);}catch(e){error=e.message;}finally{pending=false;}}
 $: visible=rows.filter(r=>showCompose||!r.compose);
</script>
<div class="toolbar"><label>Docker host<select bind:value={hostId} onchange={load}>{#each hosts as host}<option value={host.id}>{host.name}</option>{/each}</select></label><div class="toolbar-actions"><label class="inline-option"><input type="checkbox" bind:checked={showCompose}/> Show Compose containers</label><button onclick={load} disabled={pending}>Refresh containers</button><button onclick={()=>{creation=true;typed='';error='';}} disabled={!hostId}>+ Create container</button></div></div>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if pending}<p>Working…</p>{/if}
<div class="stack-grid">{#each visible as row}<article class="stack-card"><div class="card-top"><span class={`pill ${row.State}`}>{row.State}</span><span class="host-tag">{row.compose?'Compose':'Standalone'}</span></div><h2>{row.Names}</h2><code class="directory">{row.Image}</code><p>{row.Status}</p><p>{row.Ports||'No published ports'}</p>
{#if !row.compose}<div class="actions"><button onclick={()=>ask(row,'start')}>Start</button><button onclick={()=>ask(row,'stop')}>Stop</button><button onclick={()=>ask(row,'restart')}>Restart</button><button onclick={()=>ask(row,'update')}>Update</button><button class="danger-text" onclick={()=>ask(row,'remove')} disabled={row.State==='running'}>Remove</button></div>{/if}
<div class="secondary-actions"><button onclick={()=>onlogs({id:row.ID,name:row.Names,host_id:hostId,container:true})}>Live logs</button><button onclick={()=>onterminal(hostId,row.ID,row.Names)} disabled={row.State!=='running'}>Terminal</button>{#each checkpoints.filter(p=>p.new_id===row.ID) as point}<button onclick={()=>ask(row,'rollback',point)}>Restore previous version · {new Date(point.created*1000).toLocaleDateString()}</button>{/each}</div></article>{/each}</div>
{#if !pending&&!visible.length}<p>No {showCompose?'':'standalone '}containers found on this host.</p>{/if}
{#if confirm}<dialog class="modal" use:dialog aria-label="Confirm container action" oncancel={()=>confirm=null} onclose={()=>confirm=null}><button class="modal-close" onclick={()=>confirm=null} aria-label="Close container confirmation">×</button><h2>{confirm.action} · {confirm.row.Names}</h2><p>{confirm.action==='update'?'Pull the image and recreate this container with its existing configuration and mounts. The original is retained for rollback. This interrupts the service.':confirm.action==='rollback'?'Restore the previous container and image. Application data is preserved, so this does not undo database migrations.':confirm.action==='remove'?'Remove the stopped container. Its Docker volumes are preserved.':'This changes the container’s running state and may interrupt its service.'}</p><form onsubmit={act}><label>Type {confirm.row.Names}<input bind:value={typed} autocomplete="off"/></label><button class="primary" disabled={pending||typed!==confirm.row.Names}>Confirm</button></form>{#if error}<p class="error" role="alert">{error}</p>{/if}</dialog>{/if}
{#if creation}<dialog class="modal wide-modal" use:dialog aria-label="Create standalone container" oncancel={()=>creation=false} onclose={()=>creation=false}><button class="modal-close" onclick={()=>creation=false} aria-label="Close container creation">×</button><h2>Create standalone container</h2><form onsubmit={create}><label>Name<input bind:value={form.name} required/></label><label>Image reference<input bind:value={form.image} required placeholder="registry/image:tag"/></label><label>Command override (one argument per line, optional)<textarea bind:value={command} rows="2"></textarea></label><label>Environment (NAME=value, one per line)<textarea bind:value={environment} rows="3"></textarea></label><label>Published ports (host:container[/tcp|udp], one per line)<textarea bind:value={ports} rows="2" placeholder="8080:80"></textarea></label><label>Mounts (volume-or-host-path:/container/path[:ro])<textarea bind:value={mounts} rows="2" placeholder="my-data:/data"></textarea></label><label>Restart policy<select bind:value={form.restart}>{#each ['no','always','unless-stopped','on-failure'] as policy}<option>{policy}</option>{/each}</select></label><label class="inline-option"><input type="checkbox" bind:checked={form.start}/> Start after creation</label><label>Type {form.name||'the container name'}<input bind:value={typed}/></label><button class="primary" disabled={pending||!form.name||typed!==form.name}>Pull image and create</button>{#if error}<p class="error" role="alert">{error}</p>{/if}</form></dialog>{/if}
